/* Item link */
.aa-item {
  position: relative;
  display: inline-block;
}
.aa-item-name {
  font-weight: bold;
}

/* Tooltip box: hidden until the item is hovered */
.aa-tooltip {
  display: none;
  position: absolute;
  left: 100%;
  top: 0;
  z-index: 1000;
  margin-left: 8px;
  width: 300px;
  padding: 8px 10px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  color: #d8d2c4;
  font-size: 12px;
  line-height: 1.45;
  text-align: left;
  white-space: normal;
  pointer-events: none;
}
.aa-item:hover .aa-tooltip {
  display: block;
}

/* Header: icon + name + grade */
.aa-tt-header {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-bottom: 4px;
}
.aa-tt-icon img {
  display: block;
  border: 1px solid #000;
}
.aa-tt-title {
  display: flex;
  flex-direction: column;
}
.aa-tt-name {
  font-size: 14px;
  font-weight: bold;
}
.aa-tt-grade {
  font-size: 11px;
}

/* Body lines */
.aa-tt-line {
  display: block;
}
.aa-tt-row {
  display: flex;
  justify-content: space-between;
}
.aa-tt-type {
  color: #c8c8c8;
}
.aa-tt-bind {
  color: #e0c070;
}
.aa-tt-stats {
  color: #ffffff;
}
.aa-tt-effects {
  color: #6fcf5f;
}
.aa-tt-desc {
  color: #c9b48a;
  font-style: italic;
}
.aa-tt-sep {
  display: block;
  height: 1px;
  margin: 5px 0;
  background: linear-gradient(to right, transparent, #6a5d48, transparent);
}

/* Sell price */
.aa-coin {
  margin-left: 6px;
}
.aa-gold::after {
  content: " g";
  color: #e8c050;
}
.aa-silver::after {
  content: " s";
  color: #c0c0c0;
}
.aa-copper::after {
  content: " c";
  color: #c87840;
}

/* Item grade colours (from item_grades.color_argb in the game database) */
.aa-grade-crude .aa-item-name,
.aa-grade-crude .aa-tt-name,
.aa-grade-crude .aa-tt-grade { color: #ba976d; }

